from pedidos.textos import normalizar


def crear_materiales_desde_items(apps, schema_editor):
    """Backfill: crea el catálogo a partir de los ítems existentes.

    Por cada detalle distinto se crea un ``Material`` con la clave normalizada y
    se enlaza el ítem. Si dos detalles normalizan a la misma clave (p.ej.
    ``Cemento`` y ``cemento``) se reutiliza un único material: agruparlos es
    justamente el objetivo del catálogo.

    Lo que el backfill NO puede resolver son equivalencias semánticas
    (``50kg`` vs ``50 kilogramos``): quedan como materiales distintos y el
    administrador los unifica desde /materiales/.
    """
    Material = apps.get_model('pedidos', 'Material')
    ItemNotaPedido = apps.get_model('pedidos', 'ItemNotaPedido')

    for detalle in (
        ItemNotaPedido.objects.exclude(detalle='')
        .order_by('detalle')
        .values_list('detalle', flat=True)
        .distinct()
    ):
        clave = normalizar(detalle)
        if not clave:
            continue
        material, _ = Material.objects.get_or_create(
            clave=clave, defaults={'nombre': detalle[:200]}
        )
        ItemNotaPedido.objects.filter(detalle=detalle).update(material=material)


def sin_material(apps, schema_editor):
    """Deshace el backfill (los ítems quedan sin material, el catálogo se borra)."""
    ItemNotaPedido = apps.get_model('pedidos', 'ItemNotaPedido')
    ItemNotaPedido.objects.update(material=None)
    apps.get_model('pedidos', 'Material').objects.all().delete()


